DROP TABLE IF EXISTS `movimientos_bancarios`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `movimientos_bancarios` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `banco` varchar(100) NOT NULL,
  `fecha` date NOT NULL,
  `fecha_movimiento` date DEFAULT NULL,
  `referencia` varchar(100) NOT NULL,
  `referencia_bancaria` varchar(100) DEFAULT NULL,
  `descripcion` text DEFAULT NULL,
  `descripcion_banco` text DEFAULT NULL,
  `importe` decimal(12,2) NOT NULL,
  `monto` decimal(12,2) DEFAULT NULL,
  `tipo` enum('credito','debito') NOT NULL DEFAULT 'credito',
  `tipo_movimiento` enum('credito','debito') NOT NULL DEFAULT 'credito',
  `estado` enum('disponible','conciliado','anulado') NOT NULL DEFAULT 'disponible',
  `lote_importacion` varchar(50) DEFAULT NULL,
  `creado_en` timestamp NOT NULL DEFAULT current_timestamp(),
  `actualizado_en` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_mov_estado` (`estado`),
  KEY `idx_mov_estado_fecha` (`estado`,`fecha`,`importe`),
  KEY `idx_mov_referencia` (`referencia`)
) ENGINE=InnoDB AUTO_INCREMENT=595 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

